-- OFO 2021 reference data for KatisoBiz Jobs.
-- Generated by scripts/seed-ofo-2021.mjs from docs/OFO-Codes-2021.xlsx
-- (Organising Framework for Occupations, Version 2021, DHET).
-- Do not hand-edit the insert blocks; re-run the script instead.
--
-- Codes are text, never integers: the digit string is the identity, and a
-- numeric cast would destroy any future leading zero. The hierarchy is
-- explicit parent-child, one table per OFO level.

create extension if not exists pg_trgm with schema extensions;

create table jobs_ofo_major_groups (
  code text primary key,
  label text not null
);

create table jobs_ofo_sub_major_groups (
  code text primary key,
  major_code text not null references jobs_ofo_major_groups(code),
  label text not null
);

create table jobs_ofo_minor_groups (
  code text primary key,
  sub_major_code text not null references jobs_ofo_sub_major_groups(code),
  label text not null
);

create table jobs_ofo_unit_groups (
  code text primary key,
  minor_code text not null references jobs_ofo_minor_groups(code),
  label text not null
);

create table jobs_ofo_occupations (
  code text primary key,
  unit_code text not null references jobs_ofo_unit_groups(code),
  title text not null,
  is_trade boolean not null default false,
  is_green boolean not null default false
);

create table jobs_ofo_specialisations (
  id uuid primary key default gen_random_uuid(),
  occupation_code text not null references jobs_ofo_occupations(code),
  title text not null,
  unique (occupation_code, title)
);

-- Curated skills, bound to one branch of the hierarchy. The foreign key is
-- what makes a cross-branch skill structurally impossible rather than merely
-- filtered out: a skill row belongs to exactly one sub-major group, and the
-- UI derives that group from the chosen occupation's code prefix.
create table jobs_ofo_skills (
  id uuid primary key default gen_random_uuid(),
  sub_major_code text not null references jobs_ofo_sub_major_groups(code),
  label text not null,
  unique (sub_major_code, label)
);

comment on table jobs_ofo_occupations is
  'OFO Version 2021 (DHET), seeded from docs/OFO-Codes-2021.xlsx. Codes are 6-digit text.';

create index jobs_ofo_occupations_title_trgm
  on jobs_ofo_occupations using gin (title extensions.gin_trgm_ops);
create index jobs_ofo_specialisations_title_trgm
  on jobs_ofo_specialisations using gin (title extensions.gin_trgm_ops);
create index jobs_ofo_specialisations_occupation
  on jobs_ofo_specialisations (occupation_code);
create index jobs_ofo_skills_sub_major on jobs_ofo_skills (sub_major_code);

-- Reference data: world-readable, service-role writes only.
alter table jobs_ofo_major_groups enable row level security;
alter table jobs_ofo_sub_major_groups enable row level security;
alter table jobs_ofo_minor_groups enable row level security;
alter table jobs_ofo_unit_groups enable row level security;
alter table jobs_ofo_occupations enable row level security;
alter table jobs_ofo_specialisations enable row level security;
alter table jobs_ofo_skills enable row level security;

create policy "anyone reads ofo majors" on jobs_ofo_major_groups for select using (true);
create policy "anyone reads ofo sub majors" on jobs_ofo_sub_major_groups for select using (true);
create policy "anyone reads ofo minors" on jobs_ofo_minor_groups for select using (true);
create policy "anyone reads ofo units" on jobs_ofo_unit_groups for select using (true);
create policy "anyone reads ofo occupations" on jobs_ofo_occupations for select using (true);
create policy "anyone reads ofo specialisations" on jobs_ofo_specialisations for select using (true);
create policy "anyone reads ofo skills" on jobs_ofo_skills for select using (true);

grant select on jobs_ofo_major_groups to anon, authenticated;
grant select on jobs_ofo_sub_major_groups to anon, authenticated;
grant select on jobs_ofo_minor_groups to anon, authenticated;
grant select on jobs_ofo_unit_groups to anon, authenticated;
grant select on jobs_ofo_occupations to anon, authenticated;
grant select on jobs_ofo_specialisations to anon, authenticated;
grant select on jobs_ofo_skills to anon, authenticated;

-- Occupation and experience level on the product tables. Old jobs_taxonomy
-- columns stay until the UI switches over; jobs_taxonomy is dropped at
-- close-out once nothing reads it.
alter table jobs_candidates
  add column ofo_occupation_code text references jobs_ofo_occupations(code),
  add column secondary_ofo_codes jsonb not null default '[]'::jsonb,
  add column experience_level text check (experience_level in
    ('new_starter', 'experienced', 'senior', 'management', 'executive'));

alter table jobs_vacancies
  add column ofo_occupation_code text references jobs_ofo_occupations(code),
  add column experience_level text check (experience_level in
    ('new_starter', 'experienced', 'senior', 'management', 'executive'));

create index jobs_candidates_ofo on jobs_candidates (ofo_occupation_code);
create index jobs_vacancies_ofo on jobs_vacancies (ofo_occupation_code);




















